{
  "name": "pairwise_advantage_cost_loss",
  "intuition": "This loss emphasizes pairing examples based on advantage signals and cost gaps, encouraging the model to prefer higher advantage and lower costs. The difference between advantage and cost gap signals correlates with preference strength, leading to more consistent preference modeling in RL4CO tasks.",
  "pseudocode": "scalar_loss = mean(-log_sigmoid((advantage_w - advantage_l) - (cost_gap)))",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage_cost",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    advantage_w = batch.get('advantage_w', None)\n    advantage_l = batch.get('advantage_l', None)\n    cost_gap = batch.get('cost_gap', None)\n\n    adv_diff = ops.sub(advantage_w, advantage_l)\n    cost_diff = cost_gap\n    input_signal = ops.sub(adv_diff, cost_diff)\n    loss_terms = ops.logsigmoid(ops.mul(input_signal, ops.ones_like(input_signal)))\n    # Weighted mean loss\n    weighted_loss = ops.mul(loss_terms, weight)\n    loss = ops.mean(weighted_loss)\n    return loss"
}

{
  "name": "stabilized_logsigmoid_cost_gap_no_gap_expect",
  "intuition": "Removed usage of unsupported keys (gap) from expects and replaced direct cost difference with a stabilized combination using only log_prob_w, log_prob_l, and weight. Applied clamping on the scaled log-prob difference to ensure numerical stability. This avoids referencing unavailable batch keys and retains stable margin-like behavior by focusing on log probabilities and stable scaling factors.",
