{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss encourages preference of pairs where the advantage signals (difference between preferred and less preferred) are aligned with the cost_gap, reinforcing how advantage and cost gap correspond to better ordering. Using the advantage signals and cost_gap provides a direct measure of relative quality, making the loss sensitive to preference consistency. It also leverages pairwise comparison signals to enforce ranking correctness.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l + alpha * cost_gap))",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "advantage_cost",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": "alpha can be set to scale the influence of cost_gap"
  },
  "operators_used": ["logsigmoid", "add", "mul", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    advantage_w = batch[\"advantage_w\"]\n    advantage_l = batch[\"advantage_l\"]\n    cost_gap = batch[\"cost_gap\"]\n    # Compute pairwise preference score\n    preference_score = ops.add(advantage_w, ops.mul(alpha, cost_gap))\n    # Use logsigmoid to encourage the correct ordering\n    loss_tensor = -ops.logsigmoid(preference_score)\n    # Aggregate over batch\n    return ops.mean(loss_tensor)"
}

