  "generated_loss": "def generated_loss(batch, model_output, extra):\n    scale = float(extra.get('scale', 1.0))\n    margin = float(extra.get('margin', 1.0))\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    adv_gap = ops.sub(advantage_w, advantage_l)\n    weight = batch.get('weight', None)\n    adv_diff_scaled = ops.clamp(ops.mul(scale, adv_gap), -10.0, 10.0)\n    margin_shift = ops.mul(margin, adv_gap)\n    x = ops.sub(adv_diff_scaled, margin_shift)\n    loss = ops.neg(ops.logsigmoid(x))\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return ops.mean(loss)",
